CREATE OR REPLACE FUNCTION public._touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.comentarios_contadores()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rol TEXT;
  zona TEXT;
  uid UUID;
  resultado JSONB;
BEGIN
  rol := public.current_user_rol();
  zona := public.current_user_zona();
  uid := auth.uid();
  IF rol IS NULL OR uid IS NULL THEN
    RETURN '{}'::jsonb;
  END IF;

  IF rol = 'admin' THEN
    SELECT jsonb_build_object(
      'solicitudes_pendientes',
        (SELECT COUNT(*) FROM public.comentarios_zona
         WHERE estado='abierto' AND tipo IN ('mover_zona','eliminar')),
      'comentarios_abiertos',
        (SELECT COUNT(*) FROM public.comentarios_zona
         WHERE estado='abierto' AND tipo='comentario')
    ) INTO resultado;

  ELSIF rol = 'gerencia' THEN
    SELECT jsonb_build_object(
      'mis_comentarios_activos',
        (SELECT COUNT(*) FROM public.comentarios_zona
         WHERE autor_id=uid AND tipo='comentario' AND estado='abierto'),
      'solicitudes_mias_pendientes',
        (SELECT COUNT(*) FROM public.comentarios_zona
         WHERE autor_id=uid AND tipo IN ('mover_zona','eliminar') AND estado='abierto')
    ) INTO resultado;

  ELSIF rol = 'tecnico' THEN
    SELECT jsonb_build_object(
      'comentarios_sin_responder',
        (SELECT COUNT(*) FROM public.comentarios_zona
         WHERE target_zona=zona AND tipo='comentario' AND estado='abierto'),
      'mis_solicitudes_pendientes',
        (SELECT COUNT(*) FROM public.comentarios_zona
         WHERE autor_id=uid AND tipo IN ('mover_zona','eliminar') AND estado='abierto')
    ) INTO resultado;
  ELSE
    resultado := '{}'::jsonb;
  END IF;

  RETURN resultado;
END $function$

CREATE OR REPLACE FUNCTION public.forzar_zona_por_rol()
 RETURNS trigger
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  rol_actual  TEXT;
  zona_actual TEXT;
  zona_geo    TEXT;
BEGIN
  rol_actual  := current_user_rol();
  zona_actual := current_user_zona();

  -- Normalizar: "PBA" no es una zona vial válida (es la vista panorámica del picker).
  -- Si viene "PBA", tratarlo como NULL para que la lógica siguiente lo resuelva.
  IF NEW.zona = 'PBA' THEN
    NEW.zona := NULL;
  END IF;

  -- Prioridad 1: derivar zona del partido si es reconocible.
  IF NEW.partido IS NOT NULL AND TRIM(NEW.partido) <> '' THEN
    zona_geo := zona_por_partido(NEW.partido);
    IF zona_geo IS NOT NULL THEN
      NEW.zona := zona_geo;
      RETURN NEW;
    END IF;
  END IF;

  -- Prioridad 2: si el user es operativo zonal, usar su zona.
  IF rol_actual IN (
       'tecnico', 'capataz',
       'jefe_zona', 'jefe_tecnica', 'jefe_operativa',
       'jefe_administrativa', 'jefe_automotores'
     ) AND zona_actual IS NOT NULL THEN
    NEW.zona := zona_actual;
    RETURN NEW;
  END IF;

  -- Prioridad 3: admin/gerencia sin partido reconocible → respetar lo enviado
  -- (puede ser NULL si el frontend no lo pobló). Ya no puede ser 'PBA' por
  -- el guard al inicio.
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.marcar_restauraciones_vistas()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_zona TEXT;
  v_count INTEGER := 0;
  v_c INTEGER;
BEGIN
  v_zona := current_user_zona();
  IF v_zona IS NULL AND current_user_rol() NOT IN ('admin','gerencia') THEN
    RETURN 0;
  END IF;

  -- Admin y gerencia marcan todo. Roles zonales solo su zona.
  IF current_user_rol() IN ('admin','gerencia') THEN
    UPDATE public.relevamientos SET restauracion_vista = TRUE
     WHERE restaurado_en IS NOT NULL AND NOT restauracion_vista;
    GET DIAGNOSTICS v_c = ROW_COUNT; v_count := v_count + v_c;

    UPDATE public.partes_diarios SET restauracion_vista = TRUE
     WHERE restaurado_en IS NOT NULL AND NOT restauracion_vista;
    GET DIAGNOSTICS v_c = ROW_COUNT; v_count := v_count + v_c;
  ELSE
    UPDATE public.relevamientos SET restauracion_vista = TRUE
     WHERE zona = v_zona AND restaurado_en IS NOT NULL AND NOT restauracion_vista;
    GET DIAGNOSTICS v_c = ROW_COUNT; v_count := v_count + v_c;

    UPDATE public.partes_diarios SET restauracion_vista = TRUE
     WHERE zona = v_zona AND restaurado_en IS NOT NULL AND NOT restauracion_vista;
    GET DIAGNOSTICS v_c = ROW_COUNT; v_count := v_count + v_c;
  END IF;

  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_autor_registro()
 RETURNS trigger
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rol  TEXT;
  v_zona TEXT;
BEGIN
  -- Solo poblar si autor_id no vino explícito
  IF NEW.autor_id IS NULL THEN
    NEW.autor_id := auth.uid();
  END IF;

  -- Snapshot del rol/zona del autor en el momento del INSERT
  -- (para que si el user cambia de zona/rol después, el registro histórico
  -- conserve quién era esa persona cuando cargó)
  IF NEW.autor_id IS NOT NULL AND (NEW.autor_rol IS NULL OR NEW.autor_zona IS NULL) THEN
    SELECT rol, zona INTO v_rol, v_zona
      FROM public.usuarios_perfil
     WHERE user_id = NEW.autor_id
     LIMIT 1;
    IF NEW.autor_rol  IS NULL THEN NEW.autor_rol  := v_rol; END IF;
    IF NEW.autor_zona IS NULL THEN NEW.autor_zona := v_zona; END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_caminos_alias_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    NEW.updated_at = NOW();
    NEW.updated_by = auth.uid();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_parte_diario(p_id bigint, p_motivo text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rol TEXT;
  v_zona TEXT;
  v_reg_zona TEXT;
BEGIN
  IF p_motivo IS NULL OR LENGTH(TRIM(p_motivo)) < 10 THEN
    RAISE EXCEPTION 'Motivo obligatorio (mínimo 10 caracteres)';
  END IF;

  v_rol  := current_user_rol();
  v_zona := current_user_zona();

  IF v_rol NOT IN ('admin', 'jefe_zona') THEN
    RAISE EXCEPTION 'Rol % no autorizado para borrar', v_rol;
  END IF;

  SELECT zona INTO v_reg_zona FROM public.partes_diarios WHERE id = p_id;
  IF v_reg_zona IS NULL THEN
    RAISE EXCEPTION 'Parte % no existe', p_id;
  END IF;

  IF v_rol = 'jefe_zona' AND v_reg_zona <> v_zona THEN
    RAISE EXCEPTION 'jefe_zona solo puede borrar partes de su zona (% vs %)', v_reg_zona, v_zona;
  END IF;

  UPDATE public.partes_diarios
     SET borrado_en     = NOW(),
         borrado_por    = auth.uid(),
         motivo_borrado = p_motivo
   WHERE id = p_id
     AND borrado_en IS NULL;

  RETURN p_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_relevamiento(p_id bigint, p_motivo text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rol TEXT;
  v_zona TEXT;
  v_reg_zona TEXT;
BEGIN
  IF p_motivo IS NULL OR LENGTH(TRIM(p_motivo)) < 10 THEN
    RAISE EXCEPTION 'Motivo obligatorio (mínimo 10 caracteres)';
  END IF;

  v_rol  := current_user_rol();
  v_zona := current_user_zona();

  IF v_rol NOT IN ('admin', 'jefe_zona') THEN
    RAISE EXCEPTION 'Rol % no autorizado para borrar', v_rol;
  END IF;

  SELECT zona INTO v_reg_zona FROM public.relevamientos WHERE id = p_id;
  IF v_reg_zona IS NULL THEN
    RAISE EXCEPTION 'Registro % no existe', p_id;
  END IF;

  IF v_rol = 'jefe_zona' AND v_reg_zona <> v_zona THEN
    RAISE EXCEPTION 'jefe_zona solo puede borrar registros de su zona (% vs %)', v_reg_zona, v_zona;
  END IF;

  UPDATE public.relevamientos
     SET borrado_en     = NOW(),
         borrado_por    = auth.uid(),
         motivo_borrado = p_motivo
   WHERE id = p_id
     AND borrado_en IS NULL;

  RETURN p_id;
END;
$function$
